{"check_build":{"seed":1,"code":"script({title:"Imperial Star Destroyer: Executor's Spear",description:"A long wedge-shaped Imperial capital ship with a stepped dorsal hull, command tower and glowing stern drives.",palette:{hull:"light bluish grey",shadow:"dark bluish grey",trim:"white",engine:"trans red",glass:"trans light blue"}});
const hull=[];
for(let i=0;i<24;i++){const z=-48+i*4;const w=Math.max(4,Math.round(4+i*2.5));const x=-Math.floor(w/2);hull.push(box({at:[x,0,z],size:[w,12,4],colour:i%5===0?"dark bluish grey":"light bluish grey",texture:"masonry",top:"tile"}));}
section("Wedge hull",hull);
const upper=[];
for(let i=0;i<18;i++){const z=-24+i*4;const w=Math.max(6,Math.round(8+i*2.3));upper.push(box({at:[-Math.floor(w/2),12,z],size:[w,6,4],colour:"light bluish grey",texture:"masonry",top:"tile"}));}
section("Raised dorsal deck",upper);
section("Command citadel",[
box({at:[-7,18,19],size:[14,18,17],colour:"light bluish grey",texture:"masonry",top:"tile"}),
box({at:[-5,36,24],size:[10,12,11],colour:"dark bluish grey",texture:"masonry",top:"tile"}),
box({at:[-4,48,27],size:[8,6,7],colour:"light bluish grey",texture:"masonry",top:"tile"}),
box({at:[-2,54,29],size:[4,9,4],colour:"dark bluish grey",interior:"solid"}),
]);
const greeble=[];
for(let z=-35;z<30;z+=5){const w=Math.max(8,Math.round(10+(z+24)*1.15));for(let x=-Math.floor(w/2)+3;x<Math.floor(w/2)-2;x+=5){if((Math.abs(x)+z*3)%3!==0)continue;greeble.push(place({part:"2412b",at:[x,18,z],colour:"dark bluish grey"}));if((x+z)%2===0)greeble.push(place({part:"3069b",at:[x+1,19,z],colour:"white"}));}}
section("Dorsal surface greebling",greeble);
const engines=[];
for(const x of [-12,-4,4,12]){
 engines.push(place({part:"3960",at:[x-2,12,44],colour:"trans red"}));
 engines.push(place({part:"3062b",at:[x,14,45],colour:"trans red"}));
 engines.push(place({part:"3941",at:[x-1,12,42],colour:"dark bluish grey"}));
}
section("Stern drive bank",engines);
const antenna=[];
for(const x of [-5,4])antenna.push(place({part:"3957a",at:[x,60,31],colour:"light bluish grey"}));
section("Sensor masts",antenna);"}}

